R = []
def ref(pmid, fa, au, yr, title, jr, cit, doi, pmc, typ, systems, mechs, direction, summ):
    R.append(dict(pmid=pmid, first_author=fa, authors_short=au, year=yr, title=title, journal=jr, citation=cit, doi=doi, pmcid=pmc, type=typ, systems=systems, mechs=mechs, direction=direction, summary=summ))
ref("7639117","Fitzsimmons","Fitzsimmons RJ, Ryaby JT, Magee FP, Baylink DJ",1995,"IGF-II receptor number is increased in TE-85 osteosarcoma cells by combined magnetic fields.","J Bone Miner Res","10(5):812-9","10.1002/jbmr.5650100519",None,"invitro",["muscular"],["induction","effectors"],"th","TE-85 osteoblast-like cells in a combined AC+DC field (15.3 Hz, calculated max induced potential 1e-5 V/m in medium); 30 min exposure raised IGF-II (not IGF-I) receptor number in a frequency-dependent manner, with a higher IGF-II Kd.")
